import{z as d,x as i,o as e,c as C,q as t,j as l,D as o,d as E,s as n,S as B,b as r}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"强连通分量 Tarjan / Kosaraju","description":"","frontmatter":{"title":"强连通分量 Tarjan / Kosaraju","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/scc-tarjan.md","filePath":"cs/scc-tarjan.md","lastUpdated":1791063341000}'),A={name:"cs/scc-tarjan.md"};function u(D,a,p,S,c,T){const s=i("Mermaid");return e(),C("div",null,[a[2]||(a[2]=t('<h1 id="强连通分量-tarjan-kosaraju" tabindex="-1">强连通分量 Tarjan / Kosaraju <a class="header-anchor" href="#强连通分量-tarjan-kosaraju" aria-label="Permalink to &quot;强连通分量 Tarjan / Kosaraju&quot;">​</a></h1><div class="epigraph"><p>有向图里相互可达的点落在同一块；一次 DFS 的 low 值，或正图加转置图各一次 DFS，都能在线性时间捏出这些块。</p><footer>—— 据 Tarjan, Depth-First Search and Linear Graph Algorithms, 1972；Kosaraju（未发表讲义，Sharir 1981 记述）；CLRS 第 22.5 节整理</footer></div><p><a href="/cs/randomized-algo">上一课</a>把随机化直觉收进工具箱：Las Vegas 正确、时间随机，Monte Carlo 可错、可重复压错误，硬币在算法内、不代替 NP 证书。本课程仍在图、代数、DP 与近似——不重写 Transformer，也不进入限价簿。主干<a href="/cs/dfs-edge-types">DFS 与边分类</a>已给发现/完成时刻；<a href="/cs/bcc-bridge">连通分量与桥</a>用 <code>low</code> 切无向图。缺口是<strong>有向图的强连通分量</strong>（SCC）：\\(u\\) 与 \\(v\\) 同块当且仅当 \\(u\\) 可达 \\(v\\) 且 \\(v\\) 可达 \\(u\\)。后课默认已经会缩点成 DAG。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无向连通只问「删边后是否断开」。有向图可以有环、有单向桥。SCC 是极大相互可达集。缩每个 SCC 成一点，块间边构成 DAG：再无有向环。缺口不是再证括号定理，而是把环捏成点。</p><p>Kosaraju：先对原图 DFS，记下完成时刻降序；再对转置图 \\(G^T\\) 按该序 DFS，每棵树是一个 SCC。直觉：完成晚的点更「源」；\\(G^T\\) 上从源出发扫到的，正是能互相走回来的一块。<span class="marginnote">Kosaraju 的第二次 DFS 可以类比「按离场顺序反向点名」：第一次 DFS 记下谁最后离场（完成最晚的点最「源」），转置图把所有箭头掉头，从最源的点出发能扫成一棵树的，恰好是互相能走回来的一块——掉头是为了把「我去得了你」翻转成「你回得来我」。</span></p><p>Tarjan：一次 DFS。<code>low[u]</code> 为 \\(u\\) 的子树能摸到的、仍在栈上的最老祖先发现时刻。点进栈；当 <code>low[u]=d[u]</code>，\\(u\\) 到栈顶弹出为一块。与无向桥的 <code>low</code> 同类，但栈维护的是「当前未完成的 SCC 候选」。</p><h3 id="两种线性-不是两种定义" tabindex="-1">两种线性，不是两种定义 <a class="header-anchor" href="#两种线性-不是两种定义" aria-label="Permalink to &quot;两种线性，不是两种定义&quot;">​</a></h3><p>SCC 是图论对象。算法是实现。不要把第二次 DFS 当成「必须转置」的定义；也不要把 Tarjan 的栈当成 Kosaraju 的完成序。二者都是 \\(\\Theta(V+E)\\)。</p><p><span class="marginnote">Tarjan 1972 同时给 SCC 与双连通。Kosaraju 的两次 DFS 经 Sharir 1981 进入教材。CLRS 22.5 写 Kosaraju。后课 2-SAT 把蕴涵图画成 SCC。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>任选其一。Kosaraju 实现干净：完成时刻数组 + 邻接表转置。Tarjan 省一次图扫描，需栈与 <code>low</code>。缩点：为每个 SCC 编号，原边若两端不同块则连块边，去重。</p>',12)),(e(),l(B,null,{default:o(()=>[n(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E6%9C%89%E5%90%91%E5%9B%BE%20G%22%5D%20--%3E%20DFS%5B%22DFS%EF%BC%9A%E6%97%B6%E5%88%BB%E6%88%96%20low%22%5D%0A%20%20DFS%20--%3E%20SCC%5B%22%E5%BC%BA%E8%BF%9E%E9%80%9A%E5%88%86%E9%87%8F%22%5D%0A%20%20SCC%20--%3E%20DAG%5B%22%E7%BC%A9%E7%82%B9%20DAG%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("p",null,"孤立点是平凡 SCC。有向环上全体点同一块。DAG 本身每个点一块。",-1)),a[4]||(a[4]=r("p",null,[r("span",{class:"marginnote"},"数字实例：设 \\(d[a]=1\\)，\\(a\\to b\\to a\\) 构成环——b 回看时发现 a 还在栈上，取 \\(\\mathrm{low}[b]=\\min(d[b],d[a])=1\\)，回传后 \\(\\mathrm{low}[a]\\) 也是 1，与 \\(d[a]\\) 相等——a 弹栈时把 b 一起带走，环上全体落进同一块。这就是「栈上候选」的实际含义。")],-1)),a[5]||(a[5]=r("h2",{id:"机制",tabindex:"-1"},[E("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=r("p",null,"缩点 DAG 上可拓扑。路径存在性：块内任意两点互相达；块间沿 DAG 走。2-SAT、差分约束的可行、有向图的传递闭包加速，都先缩点。不要在原图上对每个点对再 DFS——那是 \\(O(V(V+E))\\)。",-1)),(e(),l(B,null,{default:o(()=>[n(s,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22%E8%AE%BF%E9%97%AE%20u%EF%BC%9A%E8%AE%B0%E5%8F%91%E7%8E%B0%E6%97%B6%E5%88%BB%20d%5Bu%5D%EF%BC%8Cu%20%E8%BF%9B%E6%A0%88%5D%20--%3E%20NB%5B%E9%81%8D%E5%8E%86%E5%90%8E%E7%BB%A7%20v%22%5D%0A%20%20NB%20--%3E%7C%22v%20%E6%9C%AA%E8%AE%BF%E9%97%AE%22%7C%20REC%5B%22%E9%80%92%E5%BD%92%20v%EF%BC%8C%E5%9B%9E%E6%9D%A5%E5%8F%96%3Cbr%2F%3Elow%5Bu%5D%20%3D%20min(low%5Bu%5D%2C%20low%5Bv%5D)%22%5D%0A%20%20NB%20--%3E%7C%22v%20%E8%BF%98%E5%9C%A8%E6%A0%88%E4%B8%8A%22%7C%20BACK%5B%22u%20%E6%91%B8%E5%88%B0%E6%9B%B4%E8%80%81%E7%9A%84%20v%3Cbr%2F%3Elow%5Bu%5D%20%3D%20min(low%5Bu%5D%2C%20d%5Bv%5D)%22%5D%0A%20%20REC%20--%3E%20TEST%7B%22low%5Bu%5D%20%3D%20d%5Bu%5D%20%3F%22%7D%0A%20%20BACK%20--%3E%20TEST%0A%20%20TEST%20--%3E%7C%22%E5%90%A6%22%7C%20UP%5B%22%E6%8A%8A%20low%20%E4%BC%A0%E7%BB%99%E7%88%B6%E8%8A%82%E7%82%B9%E7%BB%A7%E7%BB%AD%22%5D%0A%20%20TEST%20--%3E%7C%22%E6%98%AF%22%7C%20POP%5B%22u%20%E5%88%B0%E6%A0%88%E9%A1%B6%E5%85%A8%E9%83%A8%E5%BC%B9%E5%87%BA%EF%BC%9A%E4%B8%80%E4%B8%AA%20SCC%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=t('<p><span class="marginnote">初学者容易把缩点后 DAG 的边数当成增长率来估复杂度，实际上缩点本身的成本由原图的 \\(V+E\\) 决定，块数与块边数是输出而非输入规模；最坏情形（每个点自成一个块）块边可达 \\(E\\) 条，去重要用哈希或排序，别忘计入。</span></p><p>与无向 BCC：对象不同。桥是边割；SCC 是点的可达等价类。Tarjan 的 <code>low</code> 在两类问题里公式相近，栈与无向边的处理不要混抄。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 2-SAT 的赋值、不写欧拉回路。不引入 Gabow 的第三种线性算法细节。有向图的桥（弧割）与 2-边连通是另一套，不插入。后课默认：SCC 可线性算出；缩点后是 DAG。</p><p>下一课把布尔公式的 2-CNF 变成蕴涵图，SCC 决定可否满足。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>强连通 = 相互可达；缩点得 DAG。</li><li>Kosaraju 两次 DFS；Tarjan 一次 DFS + 栈。</li><li>代价 \\(\\Theta(V+E)\\)；后课当黑盒用。</li><li>出处：Tarjan, 1972；Sharir 记述的 Kosaraju；CLRS 第 22.5 节。</li></ul>',7))])}const F=d(A,[["render",u]]);export{m as __pageData,F as default};
